#include <iostream>
#include <vector>

int main() {
    std::vector<int> datos{3, 7};
    int anterior = datos.at(0);
    for (auto& valor : datos) { valor += 2; }
    int menor = datos.at(0);
    for (int valor : datos) {
        if (valor < menor) { menor = valor; }
    }
    std::cout << anterior << " " << menor;
    return 0;
}
